.wppo-video-placeholder {
	position: relative;
	cursor: pointer;
	max-width: 100%;
	border-radius: 4px;
	overflow: hidden;
	aspect-ratio: 16 / 9;
	background-color: var(--wppo-bg-secondary, #f0f0f1);

	img {
		display: block;
		width: 100%;
		height: 100%;
		object-fit: cover;
	}

	picture {
		display: block;
		width: 100%;
	}
}

